contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount) public payable {
        require(address(this).balance >= amount, "not enough balance");

        c.fallback{value: amount}();

        address ownerBefore = c.owner();
        uint256 balanceBefore = address(c).balance;

        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(
            (msg.sender != ownerBefore && reverted) ||
            (msg.sender == ownerBefore && !reverted && address(c).balance == 0 && address(this).balance >= balanceBefore)
        );
    }

    receive() external payable {}
}

