        require(sent, "funding failed");
        beforeBalance = address(c).balance;
        try c.withdraw(value) {
            reverted = false;
            afterBalance = address(c).balance;
        } catch {
            reverted = true;
        }
        assert(
            (value <= beforeBalance && !reverted && afterBalance == beforeBalance - value) ||
            (value > beforeBalance && reverted)
        );
    }

    receive() external payable {}
}

